changeSet.sql:
ALTER TABLE notifications_v2.notifications ADD CONSTRAINT notifications_priority_check CHECK (priority BETWEEN 0 AND 100);
ALTER TABLE notifications_v2.notifications ADD CONSTRAINT notifications_revision_check CHECK (revision > 0);
ALTER TABLE notifications_v2.notifications ADD CONSTRAINT notifications_template_version_check CHECK (template_version > 0);
ALTER TABLE notifications_v2.notifications ADD CONSTRAINT notifications_schedule_check CHECK ((schedule_kind = 'immediate' AND scheduled_at IS NULL AND cron_expression IS NULL) OR (schedule_kind = 'once' AND scheduled_at IS NOT NULL AND cron_expression IS NULL) OR (schedule_kind = 'cron' AND scheduled_at IS NULL AND cron_expression IS NOT NULL));
ALTER TABLE notifications_v2.notifications ADD CONSTRAINT notifications_cron_bounds_check CHECK (schedule_kind = 'cron' OR (starts_at IS NULL AND ends_at IS NULL));
ALTER TABLE notifications_v2.notifications ADD CONSTRAINT notifications_bounds_check CHECK (ends_at IS NULL OR starts_at IS NULL OR ends_at > starts_at);
ALTER TABLE notifications_v2.notifications ADD CONSTRAINT notifications_ttl_check CHECK (delivery_ttl_seconds IS NULL OR delivery_ttl_seconds > 0);
ALTER TABLE notifications_v2.notifications ADD CONSTRAINT notifications_misfire_check CHECK (misfire_policy IN ('skip','fire_once'));
ALTER TABLE notifications_v2.notifications ADD CONSTRAINT notifications_status_check CHECK (status IN ('active','paused','completed','cancelled'));
ALTER TABLE notifications_v2.notification_events ADD CONSTRAINT notification_events_revision_check CHECK (revision > 0);
ALTER TABLE notifications_v2.notification_events ADD CONSTRAINT notification_events_template_version_check CHECK (template_version > 0);
ALTER TABLE notifications_v2.notification_events ADD CONSTRAINT notification_events_attempts_check CHECK (expansion_attempt_count >= 0);
ALTER TABLE notifications_v2.notification_events ADD CONSTRAINT notification_events_expiry_check CHECK (expires_at IS NULL OR expires_at > scheduled_at);
ALTER TABLE notifications_v2.notification_events ADD CONSTRAINT notification_events_status_check CHECK (status IN ('pending','expanding','ready','failed','cancelled'));
ALTER TABLE notifications_v2.notification_events ADD CONSTRAINT notification_events_lease_check CHECK ((status = 'expanding' AND lease_token IS NOT NULL AND lease_expires_at IS NOT NULL) OR (status <> 'expanding' AND lease_token IS NULL AND lease_expires_at IS NULL));
ALTER TABLE notifications_v2.notification_deliveries ADD CONSTRAINT notification_deliveries_priority_check CHECK (priority BETWEEN 0 AND 100);
ALTER TABLE notifications_v2.notification_deliveries ADD CONSTRAINT notification_deliveries_attempts_check CHECK (attempt_count >= 0);
ALTER TABLE notifications_v2.notification_deliveries ADD CONSTRAINT notification_deliveries_availability_check CHECK (available_at >= eligible_at);
ALTER TABLE notifications_v2.notification_deliveries ADD CONSTRAINT notification_deliveries_status_check CHECK (status IN ('pending','processing','retrying','accepted','delivered','failed','dead_lettered','suppressed','expired','cancelled'));
ALTER TABLE notifications_v2.notification_deliveries ADD CONSTRAINT notification_deliveries_lease_check CHECK ((status = 'processing' AND lease_token IS NOT NULL AND lease_expires_at IS NOT NULL) OR (status <> 'processing' AND lease_token IS NULL AND lease_expires_at IS NULL));
ALTER TABLE notifications_v2.notification_delivery_attempts ADD CONSTRAINT notification_delivery_attempts_number_check CHECK (attempt_number > 0);
ALTER TABLE notifications_v2.notification_delivery_attempts ADD CONSTRAINT notification_delivery_attempts_status_check CHECK (status IN ('started','accepted','transient_failure','permanent_failure','unknown'));
ALTER TABLE notifications_v2.notification_templates ADD CONSTRAINT notification_templates_version_check CHECK (version > 0);
ALTER TABLE notifications_v2.notification_types ADD CONSTRAINT notification_types_code_check CHECK (code IN ('update','promotion','alert','event','security'));
ALTER TABLE notifications_v2.notification_modes ADD CONSTRAINT notification_modes_code_check CHECK (code IN ('sms','email','in_app'));
ALTER TABLE notifications_v2.notification_providers ADD CONSTRAINT notification_providers_rate_check CHECK (requests_per_second IS NULL OR requests_per_second > 0);
ALTER TABLE notifications_v2.notification_providers ADD CONSTRAINT notification_providers_concurrency_check CHECK (max_concurrency > 0);
ALTER TABLE notifications_v2.notification_routes ADD CONSTRAINT notification_routes_attempts_check CHECK (max_attempts > 0);
ALTER TABLE notifications_v2.notification_routes ADD CONSTRAINT notification_routes_retry_check CHECK (retry_initial_seconds > 0 AND retry_max_seconds >= retry_initial_seconds);
ALTER TABLE notifications_v2.user_quiet_hours ADD CONSTRAINT user_quiet_hours_window_check CHECK (start_time <> end_time);

